INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001130190','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001130190","revision":1,"targetId":"80000000-0000-4000-8000-000000011319","prompt":"Die neue Fabrik wird im ___ am Stadtrand zwischen anderen Werkhallen gebaut.","instruction":{"en":"Choose the noun or noun form that best completes the sentence.","de":"Wähle das Nomen oder die Nomenform, die den Satz sinnvoll ergänzt."},"hint":{"en":"The area is designated for factories and workshops.","de":"In diesem Gebiet stehen Fabriken und Werkhallen."},"slots":[{"id":"noun","label":"Nomen oder Form","options":[{"id":"0","text":"Wohngebiet"},{"id":"1","text":"Industriegebiet"},{"id":"2","text":"Naturschutzgebiet"},{"id":"3","text":"Spielplatz"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Industriegebiet means industrial zone here; \"Industriegebiet\" is the appropriate form.","de":"Industriegebiet bedeutet hier Industriegebiet als Gewerbezone für Fabriken; die Form „Industriegebiet“ passt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die neue Fabrik wird im Industriegebiet am Stadtrand zwischen anderen Werkhallen gebaut.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises using pinned lexical/grammar facts from apps/web/data/pos/nouns.jsonl:L1158 (50a8ff6e7cce957796111ac3b29a437da3672c79e91ad44ca6f157e43cde85db), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
